-- Starter catalogue (placeholder products from Sprints 1-2). Run after schema.sql.
-- Re-running updates these rows to the values below.

on conflict (slug) do update set name_ar = excluded.name_ar, name_en = excluded.name_en, sort = excluded.sort;

on conflict (id) do update set name_ar = excluded.name_ar, name_en = excluded.name_en, price = excluded.price, old_price = excluded.old_price, images = excluded.images, categories = excluded.categories, colors = excluded.colors, sizes = excluded.sizes, sold_out = excluded.sold_out, rating = excluded.rating, reviews = excluded.reviews, sold = excluded.sold, is_new = excluded.is_new, is_flash = excluded.is_flash, sort = excluded.sort;

on conflict (id) do update set name_ar = excluded.name_ar, name_en = excluded.name_en, description_ar = excluded.description_ar, description_en = excluded.description_en, material_ar = excluded.material_ar, material_en = excluded.material_en, color_ar = excluded.color_ar, color_en = excluded.color_en, price = excluded.price, sizes = excluded.sizes, cutout_url = excluded.cutout_url, look_url = excluded.look_url, sort = excluded.sort;
